-- Confidential vault (FR-DOC-005, 006, 007, 010, 011, 017; SRS 10.1), ADR 010.

-- ============ Part 1: tables (generated by prisma migrate diff) ============
-- AlterTable
ALTER TABLE "organizations" ADD COLUMN     "vault_reauth_minutes" INTEGER NOT NULL DEFAULT 10;

-- AlterTable
ALTER TABLE "documents" ADD COLUMN     "deleted_by" UUID,
ADD COLUMN     "legal_hold_at" TIMESTAMPTZ,
ADD COLUMN     "legal_hold_by" UUID,
ADD COLUMN     "legal_hold_reason" TEXT,
ADD COLUMN     "meta_key_id" VARCHAR(100),
ADD COLUMN     "meta_key_wrapped" BYTEA,
ADD COLUMN     "shredded_at" TIMESTAMPTZ,
ADD COLUMN     "title_enc" BYTEA,
ALTER COLUMN "title" DROP NOT NULL;

-- AlterTable
ALTER TABLE "document_versions" ADD COLUMN     "dek_wrapped_recovery" BYTEA,
ADD COLUMN     "recovery_key_id" VARCHAR(100),
ALTER COLUMN "file_name_enc" DROP NOT NULL,
ALTER COLUMN "dek_wrapped_kms" DROP NOT NULL;

-- CreateTable
CREATE TABLE "vault_reauth" (
    "family_id" UUID NOT NULL,
    "org_id" UUID NOT NULL,
    "user_id" UUID NOT NULL,
    "reauthenticated_at" TIMESTAMPTZ NOT NULL,

    CONSTRAINT "vault_reauth_pkey" PRIMARY KEY ("family_id")
);

-- CreateTable
CREATE TABLE "document_password_attempts" (
    "org_id" UUID NOT NULL,
    "document_id" UUID NOT NULL,
    "user_id" UUID NOT NULL,
    "failures" INTEGER NOT NULL DEFAULT 0,
    "locked_until" TIMESTAMPTZ,
    "updated_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "document_password_attempts_pkey" PRIMARY KEY ("document_id","user_id")
);

-- CreateTable
CREATE TABLE "document_share_links" (
    "id" UUID NOT NULL DEFAULT gen_random_uuid(),
    "org_id" UUID NOT NULL,
    "document_id" UUID NOT NULL,
    "token_hash" CHAR(64) NOT NULL,
    "password_hash" TEXT,
    "view_only" BOOLEAN NOT NULL DEFAULT false,
    "expires_at" TIMESTAMPTZ NOT NULL,
    "max_downloads" INTEGER,
    "download_count" INTEGER NOT NULL DEFAULT 0,
    "failed_attempts" INTEGER NOT NULL DEFAULT 0,
    "revoked_at" TIMESTAMPTZ,
    "revoked_by" UUID,
    "created_by" UUID NOT NULL,
    "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "last_used_at" TIMESTAMPTZ,

    CONSTRAINT "document_share_links_pkey" PRIMARY KEY ("id")
