-- CreateTable
CREATE TABLE "document_retention_rules" (
    "org_id" UUID NOT NULL,
    "category" VARCHAR(20) NOT NULL,
    "min_years" INTEGER,
    "auto_shred_years" INTEGER,
    "updated_by" UUID,
    "updated_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "document_retention_rules_pkey" PRIMARY KEY ("org_id","category")
);

-- CreateIndex
CREATE INDEX "vault_reauth_org_id_user_id_idx" ON "vault_reauth"("org_id", "user_id");

-- CreateIndex
CREATE UNIQUE INDEX "document_share_links_token_hash_key" ON "document_share_links"("token_hash");

-- CreateIndex
CREATE INDEX "document_share_links_org_id_document_id_idx" ON "document_share_links"("org_id", "document_id");

-- AddForeignKey
ALTER TABLE "vault_reauth" ADD CONSTRAINT "vault_reauth_org_id_fkey" FOREIGN KEY ("org_id") REFERENCES "organizations"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "document_password_attempts" ADD CONSTRAINT "document_password_attempts_org_id_fkey" FOREIGN KEY ("org_id") REFERENCES "organizations"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "document_password_attempts" ADD CONSTRAINT "document_password_attempts_document_id_fkey" FOREIGN KEY ("document_id") REFERENCES "documents"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "document_share_links" ADD CONSTRAINT "document_share_links_org_id_fkey" FOREIGN KEY ("org_id") REFERENCES "organizations"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "document_share_links" ADD CONSTRAINT "document_share_links_document_id_fkey" FOREIGN KEY ("document_id") REFERENCES "documents"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "document_retention_rules" ADD CONSTRAINT "document_retention_rules_org_id_fkey" FOREIGN KEY ("org_id") REFERENCES "organizations"("id") ON DELETE CASCADE ON UPDATE CASCADE;



-- ============ Part 2: rules, security (hand-written) ============

ALTER TABLE organizations
  ADD CONSTRAINT organizations_vault_reauth_check CHECK (vault_reauth_minutes BETWEEN 1 AND 60);

-- A confidential title lives only in title_enc; a shredded document may have neither.
ALTER TABLE documents DROP CONSTRAINT documents_title_check;
ALTER TABLE documents
  ADD CONSTRAINT documents_title_check CHECK (
    (title IS NOT NULL AND length(btrim(title)) BETWEEN 1 AND 300)
    OR (title IS NULL AND title_enc IS NOT NULL AND meta_key_wrapped IS NOT NULL)
    OR shredded_at IS NOT NULL),
  ADD CONSTRAINT documents_legal_hold_check CHECK (NOT legal_hold OR legal_hold_reason IS NOT NULL);

-- Confidential titles are never stored in clear. NOT VALID: titles written before this
-- migration are encrypted by the document maintenance job (the key is not in the database),
-- after which the constraint can be validated.
ALTER TABLE documents
  ADD CONSTRAINT documents_confidential_title_check CHECK (
    shredded_at IS NOT NULL OR confidentiality = 'NORMAL' OR title IS NULL) NOT VALID;

ALTER TABLE document_access_logs DROP CONSTRAINT document_access_logs_action_check;
ALTER TABLE document_access_logs
  ADD CONSTRAINT document_access_logs_action_check CHECK (action IN (
    'VIEW', 'DOWNLOAD', 'UPLOAD', 'SHARE', 'DELETE', 'ACL_CHANGE', 'PASSWORD_FAIL', 'RECOVER', 'RESTORE', 'QUARANTINE', 'UPDATE',
    'SHRED', 'TRASH_RESTORE', 'LEGAL_HOLD', 'PASSWORD_SET', 'PASSWORD_REMOVED', 'REAUTH_REQUIRED'));

ALTER TABLE document_share_links
  ADD CONSTRAINT document_share_links_limits_check CHECK (max_downloads IS NULL OR max_downloads BETWEEN 1 AND 1000),
  ADD CONSTRAINT document_share_links_count_check CHECK (download_count >= 0 AND failed_attempts >= 0);

ALTER TABLE document_retention_rules
  ADD CONSTRAINT document_retention_rules_category_check CHECK (category IN ('CONTRACT', 'NDA', 'IDENTITY', 'TAX', 'INVOICE', 'POLICY', 'CERTIFICATE', 'OTHER')),
  ADD CONSTRAINT document_retention_rules_years_check CHECK (
    (min_years IS NULL OR min_years BETWEEN 1 AND 100)
    AND (auto_shred_years IS NULL OR auto_shred_years BETWEEN 1 AND 100)
    AND (min_years IS NULL OR auto_shred_years IS NULL OR auto_shred_years >= min_years));

DO $$
DECLARE
  t TEXT;
BEGIN
  FOREACH t IN ARRAY ARRAY['vault_reauth', 'document_password_attempts', 'document_share_links', 'document_retention_rules'] LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t);
    EXECUTE format(
      'CREATE POLICY %I ON %I FOR ALL
         USING (org_id = NULLIF(current_setting(''app.org_id'', true), '''')::uuid)
         WITH CHECK (org_id = NULLIF(current_setting(''app.org_id'', true), '''')::uuid)',
      t || '_org_policy', t);
  END LOOP;
END
$$;

GRANT SELECT, INSERT, UPDATE ON vault_reauth, document_password_attempts, document_share_links TO hrvo_app;
GRANT SELECT, INSERT, UPDATE, DELETE ON document_retention_rules TO hrvo_app;
REVOKE DELETE, TRUNCATE ON vault_reauth, document_password_attempts, document_share_links FROM hrvo_app;

-- Share links are opened without a login, so before any tenant context exists. This returns
-- only the link id and its organisation for an exact token hash; everything else is read
-- afterwards under SET LOCAL app.org_id.
CREATE FUNCTION fn_share_link_lookup(p_token_hash CHAR(64))
RETURNS TABLE (id UUID, org_id UUID)
SECURITY DEFINER
SET search_path = public
LANGUAGE sql STABLE AS $$
  SELECT l.id, l.org_id FROM document_share_links l WHERE l.token_hash = p_token_hash;
$$;
REVOKE ALL ON FUNCTION fn_share_link_lookup(CHAR) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION fn_share_link_lookup(CHAR) TO hrvo_app;
